insert into public.categories (id, name, code, description, color) values
('cat-core', 'Professional Core', 'PCC', 'Foundational computer engineering and system architecture courses.', '#3b82f6'),
('cat-bs', 'Basic Science', 'BSC', 'Mathematics, physics, and computational statistics fundamentals.', '#06b6d4'),
('cat-es', 'Engineering Science', 'ESC', 'Core engineering concepts across electronics, electrical, and mechanics.', '#10b981'),
('cat-elec', 'Professional Elective', 'PEC', 'Specialized domain courses spanning AI, Cloud, Security, and Big Data.', '#8b5cf6'),
('cat-hss', 'Humanities & Social Sciences', 'HSMC', 'Professional communication, economics, and engineering ethics.', '#f59e0b'),
('cat-proj', 'Project & Internship', 'PROJ', 'Practical capstone engineering projects and industrial training.', '#ec4899')
insert into public.semesters (id, number, roman, title, subtitle, tagline, color, glow, orbit_radius, orbit_speed, planet_size, description, subject_count, credits, highlights) values
(1, 1, 'I', 'Semester 1', 'Foundation & Basic Engineering', 'Initial orbit around fundamental physical and computational principles', '#06b6d4', 'rgba(6, 182, 212, 0.4)', 2.2, 0.8, 0.28, 'Establish foundational principles in differential calculus, physics, and initial imperative C programming.', 6, 21, ARRAY['Calculus & Linear Algebra', 'C Programming (PPS)', 'Basic Electrical (BEE)', 'Engineering Graphics (EGD)']),
(2, 2, 'II', 'Semester 2', 'Core Sciences & Technical Communication', 'Expanding trajectory through electronics and advanced scientific methods', '#0ea5e9', 'rgba(14, 165, 233, 0.4)', 3.1, 0.65, 0.32, 'Deepen mathematical analysis with vector calculus and master semiconductor devices and workshop fabrication.', 5, 17, ARRAY['Vector Calculus & ODEs', 'Basic Electronics (BE)', 'Mechanical Systems (BME)', 'Technical English']),
(3, 3, 'III', 'Semester 3', 'Data Structures & Architecture Genesis', 'Entering computational core territory with linear data structures & relational schemas', '#6366f1', 'rgba(99, 102, 241, 0.4)', 4, 0.52, 0.35, 'Transition into essential computer science foundations: data structures, relational DBMS, and digital logic circuits.', 7, 21, ARRAY['Data Structures (DS)', 'Database Management (DBMS)', 'Digital Fundamentals (DF)', 'Probability & Stats (PS)']),
(4, 4, 'IV', 'Semester 4', 'Operating Systems & Algorithm Design', 'System-level orbit intersecting kernel architecture and discrete proofs', '#8b5cf6', 'rgba(139, 92, 246, 0.4)', 4.9, 0.44, 0.38, 'Tackle the bedrock of systems engineering: kernel process scheduling, OOP with Java, and processor architecture.', 6, 22, ARRAY['Operating Systems (OS)', 'Java OOP-I', 'Computer Architecture (COA)', 'Discrete Mathematics (DM)']),
(5, 5, 'V', 'Semester 5', 'Networks & Computational Theory', 'High-speed packet transport and theoretical automata mechanics', '#d946ef', 'rgba(217, 70, 239, 0.4)', 5.8, 0.36, 0.36, 'Understand the global Internet routing stack, algorithm design patterns, and enterprise software engineering.', 8, 24, ARRAY['Computer Networks (CN)', 'Analysis of Algorithms (ADA)', 'Software Engineering (SE)', 'Python for Data Science (PDS)']),
(6, 6, 'VI', 'Semester 6', 'Artificial Intelligence & Compilers', 'Deepening intelligence nodes, lexical parsing, and defensive cryptography', '#f43f5e', 'rgba(244, 63, 94, 0.4)', 6.7, 0.3, 0.34, 'Construct formal Turing machines, microprocessor assembly, enterprise Java servlets, and web applications.', 7, 23, ARRAY['Theory of Computation (TOC)', 'Microprocessor & Interfacing (MPI)', 'Advance Java (AJP)', 'Web Programming (WP)']),
(7, 7, 'VII', 'Semester 7', 'Cloud Platforms & Machine Learning', 'Distributed planetary clusters and predictive neural feature engines', '#f59e0b', 'rgba(245, 158, 11, 0.4)', 7.6, 0.24, 0.36, 'Build language compilers, implement heuristic AI agents, cryptographic security protocols, and Big Data clusters.', 7, 23, ARRAY['Compiler Design (CD)', 'Artificial Intelligence (AI)', 'Information Security (IS)', 'Big Data Analytics (BDA)']),
(8, 8, 'VIII', 'Semester 8', 'Full-Semester Industry Internship & Capstone', 'Final orbit: practical corporate immersion, major project development, and thesis defense', '#10b981', 'rgba(16, 185, 129, 0.4)', 8.5, 0.18, 0.4, 'GTU Computer Engineering full-semester Industry Internship and comprehensive Capstone project dissertation defense.', 2, 20, ARRAY['Major Project / Industry Internship', 'Capstone Engineering Dissertation', 'Full-Semester Practical Immersion'])
insert into public.subjects (id, code, name, short_name, semester_id, category_id, credits, description, important_topics, related_subject_ids) values
('sub-3110014', '3110014', 'Mathematics - I', 'Maths-1', 1, 'cat-bs', 4, 'Differential calculus, indeterminate forms, improper integrals, matrices, rank of matrix, and eigenvalues.', ARRAY['Rolle’s Theorem, Cauchy and Lagrange Mean Value Theorems', 'Indeterminate forms and L’Hospital’s Rule', 'Matrices: Rank, Echelon form, and Cayley-Hamilton Theorem', 'Eigenvalues and Eigenvectors with diagonalisation', 'Beta and Gamma functions with evaluation of integrals', 'Fourier Series for periodic waveforms'], ARRAY['sub-3110015', 'sub-3130006']),
('sub-3110018', '3110018', 'Physics', 'Physics', 1, 'cat-bs', 4, 'Optics, interference, diffraction, lasers, fiber optics, quantum mechanics, and magnetic materials.', ARRAY['Interference in thin films and Newton’s rings apparatus', 'Fraunhofer diffraction at single and double slits', 'Laser principles: Population inversion, Ruby & He-Ne lasers', 'Fiber optics: Numerical aperture and acceptance angle', 'De-Broglie wavelength & Schrodinger’s wave equation', 'Superconductivity and Meissner effect'], ARRAY['sub-3110016', 'sub-3130704']),
('sub-3110005', '3110005', 'Basic Electrical Engineering', 'BEE', 1, 'cat-es', 4, 'DC circuits analysis, AC circuits, magnetic circuits, single-phase transformers, and electrical safety.', ARRAY['Mesh and Nodal analysis with Kirchhoff laws', 'Thevenin, Norton, and Superposition theorems', 'AC series and parallel RLC resonance circuits', 'Three-phase balanced star and delta connections', 'Transformer equivalent circuit, losses, and efficiency', 'Earthing methods and MCB working principles'], ARRAY['sub-3110016', 'sub-3130704']),
('sub-3110003', '3110003', 'Programming for Problem Solving', 'PPS', 1, 'cat-es', 4, 'Foundational programming in C: control structures, arrays, pointers, functions, structures, and file I/O.', ARRAY['Algorithms, flowcharts, and operator precedence', 'Control statements (nested if-else, switch-case, while, for loops)', '1D and 2D arrays, string manipulation functions', 'Recursion and call by value vs call by reference', 'Pointer arithmetic, dynamic memory allocation (malloc, calloc, free)', 'Structures, unions, and file pointers with fread/fwrite'], ARRAY['sub-3130702', 'sub-3140705']),
('sub-3110013', '3110013', 'Engineering Graphics & Design', 'EGD', 1, 'cat-es', 3, 'Engineering curves, projection of points, lines, planes, solids, section of solids, isometric drawings, and CAD.', ARRAY['Conic sections: Ellipse, Parabola, and Involutes of polygons', 'Projection of straight lines inclined to both reference planes', 'Projections of planes (polygons, circles) with auxiliary planes', 'Projections of regular solids (prisms, pyramids, cones, cylinders)', 'Orthographic to Isometric view conversions', 'Computer-Aided Drafting (CAD) primitive commands'], ARRAY['sub-3110006', 'sub-3110012']),
('sub-3110007', '3110007', 'Environmental Science', 'ES', 1, 'cat-hss', 2, 'Ecology, ecosystems, renewable and non-renewable energy, environmental pollution, solid waste, and green engineering.', ARRAY['Ecosystem structure, food chains, and ecological pyramids', 'Air, water, soil, noise, and marine pollution control', 'Solar, wind, biomass, and geothermal renewable energy', 'Municipal solid waste management and 3R principles', 'Environmental Impact Assessment (EIA) methodology', 'Global climate change, ozone layer depletion, and acid rain'], ARRAY['sub-3140709', 'sub-3150709']),
('sub-3110015', '3110015', 'Mathematics - II', 'Maths-2', 2, 'cat-bs', 4, 'Vector calculus, gradient, divergence, curl, multiple integrals, Green and Stokes theorems, first and higher order ODEs.', ARRAY['Directional derivatives, gradient, divergence, and curl vectors', 'Line, surface, and volume multiple integrals', 'Green’s Theorem in plane, Gauss Divergence, and Stokes Theorems', 'First order ODEs: Exact equations and integrating factors', 'Higher order linear ODEs with constant coefficients and Cauchy-Euler', 'Series solution of ODEs: Legendre polynomials and Bessel functions'], ARRAY['sub-3110014', 'sub-3130006']),
('sub-3110016', '3110016', 'Basic Electronics', 'BE', 2, 'cat-es', 4, 'Semiconductor diodes, rectifiers, BJT biasing and configurations, operational amplifiers, and boolean logic gates.', ARRAY['PN junction diode characteristics, load line, and breakdown', 'Half-wave and full-wave bridge rectifiers with capacitor filters', 'Zener diode voltage regulator design', 'Bipolar Junction Transistor (BJT): CE, CB, CC biasing and stability', 'Operational Amplifier (Op-Amp 741): Inverting, non-inverting, summer', 'Digital logic gates, De-Morgan laws, and Boolean reduction'], ARRAY['sub-3110005', 'sub-3130704']),
('sub-3110006', '3110006', 'Basic Mechanical Engineering', 'BME', 2, 'cat-es', 4, 'Thermodynamics laws, steam generation, internal combustion engines, pumps, compressors, and power transmission.', ARRAY['Zeroth, First, and Second Laws of Thermodynamics', 'Properties of steam, steam boilers, and Rankine cycle basics', 'Four-stroke and two-stroke petrol (Otto) and diesel engines', 'Reciprocating and centrifugal air compressors', 'Centrifugal and reciprocating pumps working principles', 'Belt drives, gear trains, and clutches for power transmission'], ARRAY['sub-3110013', 'sub-3110012']),
('sub-3110002', '3110002', 'English for Communication', 'English', 2, 'cat-hss', 2, 'Vocabulary enrichment, technical reporting, formal business correspondence, presentation skills, and phonetics.', ARRAY['Grammar mechanics: Subject-verb agreement, tenses, active/passive voice', 'Technical report writing: Feasibility and investigative reports', 'Business correspondence: Email etiquette, inquiry letters, resumes', 'Phonetic transcription and pronunciation techniques', 'Reading comprehension and technical precis writing', 'Oral presentation strategies and non-verbal body language'], ARRAY['sub-3130004']),
('sub-3110012', '3110012', 'Workshop / Manufacturing Practices', 'Workshop', 2, 'cat-es', 3, 'Fitting shop, carpentry, tin smithy, arc and gas welding, machining operations, and safety standards.', ARRAY['Fitting shop tools, filing, sawing, and precision measurement', 'Carpentry tools, timber seasoning, and standard wood joints', 'Sheet metal tools, development of surfaces, and soldering', 'Shielded Metal Arc Welding (SMAW) and Oxy-acetylene gas welding', 'Lathe machine operations: Turning, facing, knurling, threading', 'Foundry casting processes, molding sands, and industrial safety'], ARRAY['sub-3110006', 'sub-3110013']),
('sub-3130702', '3130702', 'Data Structures', 'DS', 3, 'cat-core', 4, 'Arrays, stacks, queues, linked lists, binary trees, AVL trees, graphs, sorting, searching, and hashing algorithms.', ARRAY['Stack applications: Infix to Postfix conversion and evaluation', 'Circular queues and Double Ended Queues (Deque)', 'Singly, Doubly, and Circular Linked Lists implementations', 'Binary Search Trees: Insertion, deletion, traversals (pre, in, post)', 'AVL Trees: LL, RR, LR, RL balancing rotations', 'Graph traversals: BFS, DFS, and Dijkstra shortest path', 'Sorting algorithms: Quick Sort, Merge Sort, Heap Sort analysis', 'Hashing techniques: Collision resolution, open addressing, chaining'], ARRAY['sub-3110003', 'sub-3150703', 'sub-3140708']),
('sub-3130703', '3130703', 'Database Management Systems', 'DBMS', 3, 'cat-core', 4, 'ER modeling, relational algebra, SQL DDL/DML, normalization (1NF to BCNF), transaction ACID properties, and indexing.', ARRAY['Entity-Relationship (ER) model and conversion to Relational schemas', 'Relational algebra operations: Select, Project, Join, Union, Set Difference', 'Advanced SQL: Subqueries, correlated queries, views, group by, joins', 'Functional dependencies and normal forms: 1NF, 2NF, 3NF, BCNF', 'Transaction processing and ACID properties enforcement', 'Concurrency control: Lock-based protocols, 2PL, Timestamp ordering', 'Database recovery: Log-based recovery and check-pointing', 'Indexing structures: B-Trees and B+ Trees query indexing'], ARRAY['sub-3130702', 'sub-3150711']),
('sub-3130704', '3130704', 'Digital Fundamentals', 'DF', 3, 'cat-core', 4, 'Boolean algebra, K-map minimization, combinational logic, flip-flops, synchronous and asynchronous counters, registers.', ARRAY['Number systems: Binary, Octal, Hexadecimal, and 1s/2s complement', 'Boolean algebra theorems and standard SOP/POS representations', 'Karnaugh Maps (K-Map) 4-variable and 5-variable minimization', 'Combinational circuits: Half/Full Adder, Subtractor, Code converters', 'Multiplexers, Demultiplexers, Encoders, Decoders, and Priority Encoders', 'Flip-Flops: SR, D, JK, T flip-flops, Master-Slave configuration', 'Synchronous and Asynchronous (Ripple) counter design', 'Shift registers: SISO, SIPO, PISO, PIPO, Ring and Johnson counters'], ARRAY['sub-3110016', 'sub-3140707']),
('sub-3130006', '3130006', 'Probability and Statistics', 'PS', 3, 'cat-bs', 4, 'Random variables, probability distributions, sampling theory, hypothesis testing, ANOVA, and linear regression.', ARRAY['Conditional probability, Bayes’ Theorem, and independent events', 'Discrete distributions: Binomial and Poisson distributions', 'Continuous distributions: Normal, Exponential, and Uniform', 'Expectation, variance, moments, and moment generating functions', 'Sampling distributions: Central Limit Theorem, Student’s t, Chi-square', 'Hypothesis testing: Type I/II errors, z-test, t-test, and Chi-square test', 'Linear regression analysis and Pearson correlation coefficients', 'Analysis of Variance (ANOVA): One-way and two-way classifications'], ARRAY['sub-3110014', 'sub-3140708', 'sub-3170716']),
('sub-3130004', '3130004', 'Effective Technical Communication', 'ETC', 3, 'cat-hss', 2, 'Technical proposals, project presentations, interpersonal dynamics, business ethics, and corporate negotiations.', ARRAY['Dynamics of technical communication and structural barriers', 'Technical writing: Research papers, proposals, project reports', 'Corporate correspondence: Formal executive memos, RFP responses', 'Interpersonal skills, active listening, and cross-cultural communication', 'Group discussion strategies and personal interviews preparation', 'Persuasive public speaking and multimedia engineering presentations'], ARRAY['sub-3110002']),
('sub-3130007', '3130007', 'Indian Constitution', 'IC', 3, 'cat-hss', 0, 'Historical background, Preamble, Fundamental Rights, Directive Principles, Union Executive, Parliament, and Judiciary.', ARRAY['Historical background and making of the Indian Constitution', 'Philosophy and foundational pillars of the Preamble', 'Fundamental Rights (Articles 12-35) and Writs jurisdiction', 'Directive Principles of State Policy (DPSP) and Fundamental Duties', 'Union Executive: President, Prime Minister, and Council of Ministers', 'Parliament: Lok Sabha, Rajya Sabha, legislative lawmaking procedure', 'Judiciary: Supreme Court of India, High Courts, Judicial Review', 'Emergency provisions and Constitutional amendment procedures'], ARRAY['sub-3150709']),
('sub-3130008', '3130008', 'Design Engineering - 1A', 'DE 1A', 3, 'cat-proj', 3, 'Design thinking methodology, observation canvas, empathy canvas, ideation canvas, and product development canvas.', ARRAY['Introduction to Design Thinking and engineering innovation', 'Observation techniques: AEIOU summary framework', 'Empathy Canvas: User personas, feelings, and latent pain points', 'Ideation Canvas: Brainstorming, combining ideas, and feasibility', 'Product Development Canvas (PDC): Components, purpose, and value', 'Rough prototyping and user validation feedback loop'], ARRAY['sub-3140005', 'sub-3150001']),
('sub-3140702', '3140702', 'Operating System', 'OS', 4, 'cat-core', 4, 'Process management, CPU scheduling, semaphores, deadlock detection/avoidance, virtual memory paging, and file systems.', ARRAY['Process states, PCB, context switching, and system calls', 'CPU Scheduling: FCFS, SJF, SRTF, Priority, Round Robin, Multilevel', 'Process Synchronization: Critical section, Peterson’s algorithm, Semaphores', 'Classical IPC: Producer-Consumer, Readers-Writers, Dining Philosophers', 'Deadlocks: Characterization, Prevention, Banker’s Avoidance, Recovery', 'Memory Management: Contiguous allocation, Paging, TLB, Segmentation', 'Virtual Memory: Demand paging, FIFO, Optimal, LRU page replacement', 'Disk Scheduling: FCFS, SSTF, SCAN, C-SCAN, and RAID levels'], ARRAY['sub-3130702', 'sub-3140707', 'sub-3150710']),
('sub-3140705', '3140705', 'Object Oriented Programming - I (Java)', 'OOP-I (Java)', 4, 'cat-core', 4, 'Java fundamentals, OOP principles, inheritance, polymorphism, interfaces, packages, exception handling, and multithreading.', ARRAY['JVM, JDK, JRE architecture and bytecode execution', 'Classes, objects, constructors, this keyword, garbage collection', 'Inheritance: Method overriding, super keyword, final keyword', 'Polymorphism: Compile-time vs runtime, dynamic method dispatch', 'Abstract classes and Interfaces: Default & static interface methods', 'Java Packages, access specifiers, and classpath configuration', 'Exception Handling: try-catch-finally, throw, throws, custom exceptions', 'Multithreading: Thread lifecycle, Runnable interface, Synchronization', 'Java Collections: ArrayList, LinkedList, HashMap, Iterators'], ARRAY['sub-3110003', 'sub-3130702', 'sub-3160712']),
('sub-3140707', '3140707', 'Computer Organization & Architecture', 'COA', 4, 'cat-core', 4, 'Instruction sets, addressing modes, ALU design, Booth multiplication, pipeline hazards, cache mapping, and interrupt I/O.', ARRAY['Von Neumann vs Harvard architecture, bus interconnections', 'Instruction cycle, formats, and addressing modes', 'Computer arithmetic: Booth multiplication and Restoring/Non-restoring division', 'Control unit design: Hardwired control vs Microprogrammed control', 'Pipelining: Instruction pipeline, Structural, Data, and Control hazards', 'Memory hierarchy: Cache mapping (Direct, Associative, Set-associative)', 'Virtual memory translation, Page table structures, Cache write policies', 'I/O organization: Programmed I/O, Interrupt-driven I/O, and Direct Memory Access (DMA)'], ARRAY['sub-3130704', 'sub-3140702', 'sub-3160707']),
('sub-3140708', '3140708', 'Discrete Mathematics', 'DM', 4, 'cat-bs', 4, 'Propositional logic, set relations, lattice theory, algebraic structures, groups, planar graphs, and graph coloring.', ARRAY['Propositional and Predicate logic: Truth tables, tautology, quantifiers', 'Set relations, equivalence relations, partial orders, Hasse diagrams', 'Lattices: Distributive, modular, complemented, and Boolean lattices', 'Algebraic structures: Semigroups, Monoids, Groups, Subgroups, Abelian groups', 'Cosets, Lagrange’s Theorem, Normal subgroups, and Homomorphisms', 'Recurrence relations: Generating functions and characteristic equations', 'Graph Theory: Eulerian, Hamiltonian paths, trees, minimum spanning trees', 'Planar graphs, Euler’s formula, and chromatic graph coloring numbers'], ARRAY['sub-3130006', 'sub-3130702', 'sub-3160704']),
('sub-3140709', '3140709', 'Principles of Economics & Management', 'PEM', 4, 'cat-hss', 3, 'Demand and supply elasticity, cost analysis, market structures, break-even analysis, financial statements, and planning.', ARRAY['Basic economic concepts: Scarcity, choice, law of demand and supply', 'Elasticity of demand: Price, income, and cross elasticity', 'Cost concepts: Fixed, variable, average, marginal cost, economies of scale', 'Break-even analysis (BEA) and managerial decision making', 'Market structures: Perfect competition, Monopoly, Monopolistic, Oligopoly', 'Functions of management: Planning, organizing, staffing, directing, controlling', 'Corporate financial statements: Balance Sheet, Profit & Loss overview', 'Marketing mix: 4 Ps, product life cycle, and market segmentation'], ARRAY['sub-3130004', 'sub-3150709']),
('sub-3140005', '3140005', 'Design Engineering - 1B', 'DE 1B', 4, 'cat-proj', 3, 'Advanced prototyping, canvas refinements, design verification, user feedback integration, and MVP synthesis.', ARRAY['Refining Empathy and Ideation frameworks based on field feedback', 'Product Development Canvas validation and risk assessment', 'Designing Minimum Viable Products (MVP) with software wireframes', 'Usability testing, feedback capture grids, and iteration cycles', 'Engineering patents, intellectual property rights, and design registers', 'Final project exhibition documentation and pitch presentations'], ARRAY['sub-3130008', 'sub-3150001']),
('sub-3150710', '3150710', 'Computer Networks', 'CN', 5, 'cat-core', 4, 'OSI and TCP/IP models, framing, flow control, subnetting, IPv4/IPv6, routing protocols (OSPF, BGP), and TCP flow/congestion.', ARRAY['OSI 7-layer and TCP/IP reference architectures comparison', 'Data Link Layer: Framing, Error detection (CRC, Hamming code), Flow control', 'Sliding Window protocols: Stop-and-Wait, Go-Back-N, Selective Repeat', 'MAC protocols: CSMA/CD, CSMA/CA, Pure & Slotted ALOHA', 'Network Layer: IPv4 addressing, Subnetting, VLSM, CIDR, IPv6 headers', 'Routing algorithms: Distance Vector (RIP), Link State (OSPF), BGP', 'Transport Layer: UDP vs TCP, TCP 3-way handshake, Flow & Congestion control', 'Application Layer: DNS, HTTP/HTTPS, FTP, SMTP, DHCP protocols'], ARRAY['sub-3140702', 'sub-3160716', 'sub-3150714']),
('sub-3150703', '3150703', 'Analysis and Design of Algorithms', 'ADA', 5, 'cat-core', 4, 'Asymptotic notations, divide and conquer, greedy methods, dynamic programming, backtracking, branch & bound, and NP-completeness.', ARRAY['Asymptotic notation: Big-O, Omega, Theta, Master Theorem recurrence', 'Divide and Conquer: Merge Sort, Quick Sort complexity analysis', 'Greedy Method: Fractional Knapsack, Job Sequencing, Huffman Coding', 'Minimum Spanning Trees: Kruskal’s and Prim’s algorithms', 'Dynamic Programming: 0/1 Knapsack, LCS, Matrix Chain Multiplication', 'All-Pairs Shortest Path: Floyd-Warshall and Bellman-Ford algorithms', 'Backtracking: N-Queens problem, Sum of Subsets, Graph Coloring', 'Branch and Bound: 15-Puzzle problem, Traveling Salesperson (TSP)', 'Theory of NP-Completeness: P, NP, NP-Complete, and NP-Hard problems'], ARRAY['sub-3130702', 'sub-3140708', 'sub-3160704']),
('sub-3150711', '3150711', 'Software Engineering', 'SE', 5, 'cat-core', 4, 'Software process models, Agile Scrum, SRS documentation, UML design, architectural patterns, black/white box testing, and maintenance.', ARRAY['Software process models: Waterfall, Spiral, V-Model, Prototyping', 'Agile methodologies: Scrum framework, Sprint cycles, User Stories', 'Software Requirements Engineering: SRS documentation (IEEE 830)', 'Software Design: Cohesion, Coupling, Architectural styles, UML diagrams', 'Software Metrics: Function Point analysis, COCOMO estimation model', 'Software Testing: White-box (Basis path, Cyclomatic complexity), Black-box', 'Testing levels: Unit, Integration, System, and Acceptance testing', 'Software Maintenance, Re-engineering, and DevOps continuous integration'], ARRAY['sub-3130703', 'sub-3160713']),
('sub-3150713', '3150713', 'Python for Data Science', 'PDS', 5, 'cat-core', 4, 'Python core syntax, NumPy numerical arrays, Pandas dataframes, Matplotlib/Seaborn visualization, and exploratory data analysis.', ARRAY['Python data structures: Lists, Tuples, Dictionaries, Sets, Comprehensions', 'NumPy array creation, indexing, slicing, broadcasting, linear algebra', 'Pandas: Series, DataFrames, data ingestion, filtering, grouping, merging', 'Data cleaning: Handling missing values, duplicates, outliers, transforms', 'Data visualization: Matplotlib plots, Seaborn statistical charts', 'Exploratory Data Analysis (EDA) on real-world datasets', 'Scikit-learn introduction: Train-test splitting, data scaling, pipelines', 'Statistical summaries, correlation matrices, and feature distributions'], ARRAY['sub-3130006', 'sub-3170716', 'sub-3170722']),
('sub-3150709', '3150709', 'Professional Ethics', 'PE', 5, 'cat-hss', 2, 'Human values, moral dilemmas, codes of ethics (IEEE/ACM), engineering responsibility, whistleblower protection, and safety.', ARRAY['Moral awareness, moral dilemmas, Kohlberg’s and Gilligan’s theories', 'Codes of ethics: IEEE, ACM, NSPE professional obligations', 'Engineering as social experimentation and safety responsibility', 'Risk assessment, safety margins, and industrial disaster case studies', 'Workplace rights, whistleblowing ethics, and conflict of interest', 'Environmental ethics, sustainability, and technological stewardship', 'Intellectual Property Rights (IPR), software copyrights, and open source'], ARRAY['sub-3130007', 'sub-3140709']),
('sub-3150005', '3150005', 'Integrated Personality Development Course - I', 'IPDC-1', 5, 'cat-hss', 2, 'Self-awareness, leadership qualities, stress resilience, emotional intelligence, teamwork, and ethical civic values.', ARRAY['Self-awareness, character building, and overcoming negative habits', 'Time management techniques and productivity systems', 'Emotional quotient (EQ), handling academic and career stress', 'Leadership principles, team dynamics, and conflict resolution', 'Social responsibility, civic duties, and active citizenship', 'Inspiring case studies of transformational Indian and global leaders'], ARRAY['sub-3160003']),
('sub-3150001', '3150001', 'Design Engineering - 2A', 'DE 2A', 5, 'cat-proj', 3, 'Comprehensive domain problem identification, architectural systems canvas, patent search, and technical feasibility.', ARRAY['Specialized engineering problem identification and customer empathy', 'Prior art search and Indian/International patent mapping', 'Architectural Systems Canvas and hardware-software trade-offs', 'Techno-commercial feasibility analysis and cost modeling', 'Proof of Concept (PoC) development and laboratory benchmarking', 'Design review presentations and interim progress documentation'], ARRAY['sub-3140005', 'sub-3160001']),
('sub-3150714', '3150714', 'Cyber Security', 'CS', 5, 'cat-elec', 3, 'Vulnerability assessment, malware taxonomy, OWASP Top 10, network defense, penetration testing, and IT Act 2000.', ARRAY['Cybersecurity fundamentals: CIA triad, attack vectors, threat actors', 'Malware taxonomy: Viruses, worms, trojans, ransomware, rootkits', 'OWASP Top 10 web vulnerabilities: SQLi, XSS, CSRF, broken auth', 'Network defense: Firewalls, Intrusion Detection/Prevention (IDS/IPS)', 'Security auditing, vulnerability scanning with Nmap, Wireshark, Metasploit', 'Incident response lifecycle, digital forensics basics, and chain of custody', 'Indian Information Technology Act 2000 and cyber crime legal provisions'], ARRAY['sub-3150710', 'sub-3160716', 'sub-3170720']),
('sub-3160704', '3160704', 'Theory of Computation', 'TOC', 6, 'cat-core', 4, 'Deterministic and NFA, regular expressions, pumping lemma, context-free grammars, pushdown automata, and Turing machines.', ARRAY['Finite Automata: DFA, NFA with epsilon transitions, DFA minimization', 'Regular Expressions and equivalence with Finite Automata (Arden’s Theorem)', 'Pumping Lemma for Regular Languages and closure properties', 'Context-Free Grammars (CFG): Derivations, parse trees, ambiguity', 'Simplification of CFG: Chomsky Normal Form (CNF) and GNF', 'Pushdown Automata (PDA): Deterministic and Non-deterministic PDA', 'Pumping Lemma for Context-Free Languages and closure operations', 'Turing Machines: Standard TM, variations, universal TM, Halting Problem'], ARRAY['sub-3140708', 'sub-3150703', 'sub-3170701']),
('sub-3160707', '3160707', 'Microprocessor & Interfacing', 'MPI', 6, 'cat-core', 4, '8085/8086 microprocessor architecture, pin configurations, assembly programming, interrupts, and peripheral interfacing.', ARRAY['8085 internal architecture, register array, ALU, timing diagrams', '8086 16-bit microprocessor: Bus Interface Unit (BIU) and Execution Unit (EU)', '8086 memory segmentation, physical address generation, flag registers', '8086 addressing modes and comprehensive assembly instruction set', 'Assembly language programming: Arithmetic, logical, branch, string routines', 'Interrupt structure of 8086: Hardware and software interrupts, IVT', 'Programmable Peripheral Interface (8255 PPI): Modes 0, 1, 2 operation', 'Programmable Interrupt Controller (8259) and DMA Controller (8237/8257)'], ARRAY['sub-3130704', 'sub-3140707', 'sub-3160716']),
('sub-3160712', '3160712', 'Advance Java Programming', 'AJP', 6, 'cat-core', 4, 'JDBC, servlets, JSP, JavaBeans, Spring core fundamentals, Hibernate ORM, and RESTful web service integrations.', ARRAY['JDBC architecture, drivers, Connection, Statement, PreparedStatement, ResultSet', 'Java Servlets: Lifecycle, HTTP request/response handling, session tracking', 'JavaServer Pages (JSP): Scriptlets, expressions, directives, JSTL tags', 'JavaBeans and MVC (Model-View-Controller) web architecture', 'Spring Framework: Core container, Dependency Injection (DI), Inversion of Control', 'Hibernate ORM: Configuration, entity mappings, HQL queries, CRUD operations', 'Building RESTful web services with Spring Boot annotations', 'Java Security: Authentication, authorization, and CSRF protection'], ARRAY['sub-3140705', 'sub-3160713']),
('sub-3160713', '3160713', 'Web Programming', 'WP', 6, 'cat-core', 4, 'HTML5 semantic markup, CSS3 flexbox/grid, modern JavaScript ES6+, PHP server-side scripting, MySQL connectivity, and AJAX.', ARRAY['Semantic HTML5 elements, audio/video APIs, canvas drawing', 'CSS3 Flexbox, CSS Grid layouts, media queries for responsive web design', 'JavaScript ES6+: Arrow functions, promises, async/await, DOM manipulation', 'Client-side form validation and browser storage (localStorage, sessionStorage)', 'PHP scripting: Variables, control structures, functions, superglobals ($_GET, $_POST)', 'PHP sessions, cookies, and file upload processing', 'MySQL database integration with PHP using PDO and prepared statements', 'AJAX requests, JSON data interchange, and consuming external REST APIs'], ARRAY['sub-3130703', 'sub-3160712']),
('sub-3160716', '3160716', 'Internet of Things & Applications', 'IoT', 6, 'cat-elec', 3, 'IoT architecture, embedded sensing, Arduino/Raspberry Pi, communication protocols (MQTT, CoAP), cloud platforms, and smart cities.', ARRAY['IoT definition, physical design, logical design, and functional blocks', 'Sensors and actuators: Temperature, ultrasonic, PIR, servo motors', 'Embedded hardware platforms: Arduino Uno/Nano and ESP8266/ESP32 Wi-Fi SoC', 'Raspberry Pi single-board computer: Linux OS, GPIO programming with Python', 'IoT communication protocols: MQTT, CoAP, HTTP, WebSockets, Bluetooth LE, LoRaWAN', 'Cloud IoT platforms: ThingsSpeak, Adafruit IO, AWS IoT Core', 'Edge computing vs Cloud analytics in IoT deployments', 'Smart city, smart agriculture, and healthcare IoT applications'], ARRAY['sub-3110016', 'sub-3150710']),
('sub-3160003', '3160003', 'Integrated Personality Development Course - II', 'IPDC-2', 6, 'cat-hss', 2, 'Career planning, corporate etiquette, professional resilience, digital wellness, leadership ethics, and societal contribution.', ARRAY['Career visioning, purpose-driven goal setting, and lifelong learning', 'Corporate workplace etiquette, executive presence, and business ethics', 'Digital detox, mental wellness, and cultivating focus in a distracted world', 'Handling professional setbacks, failure resilience, and growth mindset', 'Collaborative leadership, mentorship, and building high-trust teams', 'Philanthropic engagement and technology solutions for social betterment'], ARRAY['sub-3150005']),
('sub-3160001', '3160001', 'Design Engineering - 2B', 'DE 2B', 6, 'cat-proj', 3, 'Functional prototyping, design optimization, user testing, product pitch, patent documentation, and engineering showcase.', ARRAY['High-fidelity working prototype assembly and software integration', 'Design for Manufacturability (DFM) and Design for Assembly (DFA)', 'Standardized compliance testing, user acceptance testing (UAT)', 'Comprehensive product cost estimation and business plan canvas', 'Patent application drafting and intellectual property protection', 'Final GTU Design Engineering viva voce exhibition and defense'], ARRAY['sub-3150001', 'sub-3170001']),
('sub-3170701', '3170701', 'Compiler Design', 'CD', 7, 'cat-core', 4, 'Lexical analysis, Lex/Flex, parsing techniques (LL, LR, LALR), syntax-directed translation, three-address code, and code optimization.', ARRAY['Phases of compiler and compiler construction tools (Lex, Yacc/Bison)', 'Lexical Analysis: Tokens, patterns, lexemes, regular expressions to DFA', 'Top-Down Parsing: Recursive descent, First & Follow computation, LL(1) parse tables', 'Bottom-Up Parsing: Shift-Reduce, Operator precedence, LR(0), SLR(1), LALR(1), CLR(1)', 'Syntax-Directed Translation (SDT): S-attributed and L-attributed definitions', 'Intermediate Code Generation: Quadruples, Triples, Three-Address Code (TAC)', 'Code Optimization: Basic blocks, flow graphs, loop optimization, peephole', 'Code Generation: Target machine registers, code generation algorithms'], ARRAY['sub-3160704', 'sub-3140707']),
('sub-3170716', '3170716', 'Artificial Intelligence', 'AI', 7, 'cat-core', 4, 'State space search, heuristics, A* algorithm, game playing (Minimax, Alpha-Beta pruning), knowledge representation, and expert systems.', ARRAY['AI foundations, Turing Test, rational agent architectures', 'Uninformed search: BFS, DFS, Uniform Cost Search, Iterative Deepening', 'Informed heuristic search: Greedy Best-First, A* Algorithm, AO* search', 'Adversarial game search: Minimax algorithm, Alpha-Beta pruning optimization', 'Constraint Satisfaction Problems (CSP): Backtracking, forward checking', 'Knowledge representation: First-Order Predicate Logic, Resolution principle', 'Probabilistic reasoning: Bayesian Networks, conditional independence', 'Expert systems architecture, inference engines, and rule-based systems'], ARRAY['sub-3150703', 'sub-3170722']),
('sub-3170720', '3170720', 'Information Security', 'IS', 7, 'cat-core', 4, 'Symmetric ciphers (DES, AES), asymmetric crypto (RSA, ECC), hash functions (SHA-256), digital signatures, SSL/TLS, and firewalls.', ARRAY['Security attacks, services, and cryptographic mechanisms', 'Classical encryption: Caesar, Playfair, Hill, Vigenere, Transposition', 'Symmetric key ciphers: Data Encryption Standard (DES), Advanced Encryption Standard (AES)', 'Asymmetric key cryptography: RSA algorithm, Diffie-Hellman key exchange, ECC', 'Cryptographic hash functions: MD5, SHA-256, Message Authentication Codes (MAC)', 'Digital signatures standards (DSS) and Public Key Infrastructure (PKI, X.509)', 'Transport Layer Security: SSL/TLS handshake protocol, IPsec protocols', 'Firewalls architectures, Bastion hosts, intrusion detection systems (IDS)'], ARRAY['sub-3150710', 'sub-3150714']),
('sub-3170722', '3170722', 'Big Data Analytics', 'BDA', 7, 'cat-elec', 4, 'The 5 Vs of Big Data, Hadoop Distributed File System (HDFS), MapReduce programming, Apache Spark RDDs, and NoSQL databases.', ARRAY['Big Data characteristics: Volume, Velocity, Variety, Veracity, Value', 'Apache Hadoop architecture: NameNode, DataNode, Secondary NameNode', 'Hadoop Distributed File System (HDFS) storage mechanics and replication', 'MapReduce programming paradigm: Map, Shuffle, Sort, Reduce phases', 'Hadoop ecosystem tools: Apache Pig, Apache Hive data warehousing', 'Apache Spark: In-memory computing, Resilient Distributed Datasets (RDDs)', 'NoSQL databases: Key-Value, Document (MongoDB), Columnar (Cassandra), Graph (Neo4j)', 'Big data stream processing overview: Apache Kafka and Spark Streaming'], ARRAY['sub-3130703', 'sub-3150713']),
('sub-3170717', '3170717', 'Mobile Application Development', 'MAD', 7, 'cat-elec', 4, 'Android application architecture, activities, fragments, intents, Jetpack layouts, SQLite/Room database, and Flutter cross-platform basics.', ARRAY['Android platform architecture, Android Studio IDE, project directory structure', 'Activity lifecycle, states, and navigating with explicit/implicit Intents', 'UI Layouts: ConstraintLayout, LinearLayout, RelativeLayout, ViewBinding', 'UI Components: RecyclerView, Adapters, CardView, Toolbar, Navigation Drawer', 'Fragments lifecycle, multi-pane layouts, and FragmentManager transactions', 'Persistent storage: SharedPreferences, SQLite database, Android Room ORM', 'Background processing: WorkManager, Services, Broadcast Receivers, Notifications', 'Consuming RESTful APIs using Retrofit / Volley and JSON parsing with Gson', 'Introduction to Flutter cross-platform development with Dart and Widgets'], ARRAY['sub-3140705', 'sub-3160713']),
('sub-3170718', '3170718', 'Mobile Computing & Wireless Communication', 'MCWC', 7, 'cat-elec', 3, 'Cellular network concepts, frequency reuse, handoff strategies, GSM architecture, 4G LTE, 5G NR, and Mobile IP routing.', ARRAY['Evolution of cellular communications: 1G, 2G, 3G, 4G LTE, and 5G NR', 'Cellular principles: Frequency reuse, cell sectoring, co-channel interference', 'Cellular capacity expansion: Cell splitting, microcell zone concepts', 'Handoff strategies: Hard vs soft handoff, mobile-assisted handoffs (MAHO)', 'GSM system architecture: BSS, NSS, OSS, radio channels, security algorithms', 'Mobile IP: Agent discovery, registration, tunneling, and triangle routing', 'Wireless LAN: IEEE 802.11 standards, MAC architecture, DCF and PCF modes', 'Ad-hoc networks: MANET characteristics, AODV and DSR routing protocols'], ARRAY['sub-3150710', 'sub-3160716']),
('sub-3170001', '3170001', 'Summer Internship', 'SI', 7, 'cat-proj', 2, 'Industrial practical training, real-world development exposure, professional mentorship, industry logbook, and project defense.', ARRAY['4 to 6 weeks industry immersion at approved software / engineering firms', 'Practical software engineering methodologies and team git collaboration', 'Daily maintenance of official GTU industrial training logbook', 'Preparation of comprehensive industry internship technical report', 'Company mentor evaluation, performance appraisal, and attendance proof', 'Departmental viva-voce examination and demonstration of industry projects'], ARRAY['sub-3150709', 'sub-3180701']),
('sub-3180701', '3180701', 'Major Project / Industry Internship', 'Major Project', 8, 'cat-proj', 16, 'Full-semester industry internship or comprehensive capstone product development, cloud deployment, and final GTU thesis defense.', ARRAY['Full-semester comprehensive industrial internship or major capstone project', 'Requirement specification, architectural blueprint, and design patterns', 'Full-stack development, modern frameworks, and continuous integration', 'Automated testing suites: Unit, integration, and load benchmarking', 'Cloud containerization (Docker) and production deployment (CI/CD)', 'Official GTU Engineering Dissertation compilation and final external viva defense'], ARRAY['sub-3170001', 'sub-3180001']),
('sub-3180001', '3180001', 'Capstone Engineering Dissertation & Viva', 'Capstone Viva', 8, 'cat-proj', 4, 'Research methodology, technical dissertation compilation, peer review publications, intellectual property, and external thesis evaluation.', ARRAY['Research methodology and state-of-the-art literature review synthesis', 'Engineering dissertation formatting adhering to GTU academic guidelines', 'Conference / journal paper publication preparation and peer review', 'Software copyright registration and patent filing considerations', 'Project demonstration, viva voce defense, and external panel examination'], ARRAY['sub-3180701'])
